let payload = query;
if (typeof payload === 'string') {
  try {
    payload = JSON.parse(payload);
  } catch (e) {
    return JSON.stringify({
      สำเร็จ: false,
      ข้อผิดพลาด: 'ข้อมูลนำเข้าไม่ถูกต้อง ต้องเป็น JSON ตามรูปแบบที่กำหนด',
    });
  }
}

return JSON.stringify(calculateThaiPIT(payload), null, 2);

